from jsonb_to_recordset($wall_questions$[{"id":"u03_l01_q139","lesson_id":"u03_l01","difficulty":"hard","prompt":"ما الرابط بين الدعاء بصلاح الأزواج والذرية وطلب أن يكون المؤمن قدوة للمتقين؟","options":[{"id":"o3","text":"عدم مسؤولية الإنسان عن من حوله"},{"id":"o1","text":"الرغبة في صلاح الأسرة وامتداد الخير إلى المجتمع"},{"id":"o2","text":"حصر الاهتمام بالمصلحة الخاصة"},{"id":"o4","text":"فصل الأخلاق العامة عن الأسرة"}],"correct_id":"o1","explanation":"يذكر الشرح مسؤولية المؤمن عن أهله وسعيه ليكونوا قدوة للناس.","page":97},{"id":"u03_l01_q142","lesson_id":"u03_l01","difficulty":"medium","prompt":"لماذا لا يُختزل وصف عباد الرحمن بأنهم يمشون هونًا في سرعة خطواتهم فقط؟","options":[{"id":"o3","text":"لأنه يقتصر على المشي داخل المسجد"},{"id":"o4","text":"لأنه يتعلّق بملابسهم فقط"},{"id":"o1","text":"لأنه يدل على تواضعهم وسلوكهم مع الناس"},{"id":"o2","text":"لأنه يعني اعتزال جميع الناس"}],"correct_id":"o1","explanation":"قال الدرس إن المشي هنا يشمل السيرة العملية وطريقة التعامل، وليس حركة القدمين فقط.","page":94},{"id":"u03_l01_q143","lesson_id":"u03_l01","difficulty":"hard","prompt":"إذا ردّ إنسان إساءة جاهل بكلمة طيبة بدل مجاراة الاستفزاز، فأي خُلُق قرآني تجلى؟","options":[{"id":"o3","text":"مجاراة المعتدي في فعله"},{"id":"o2","text":"ترك الالتزام بالحق"},{"id":"o4","text":"قطع كل صلة بالناس"},{"id":"o1","text":"الحلم والإعراض عن الجاهلين"}],"correct_id":"o1","explanation":"بيّن شرح الآية أن عباد الرحمن يعرضون عن الجاهلين ويواجهون الإساءة بالقول الطيب.","page":94},{"id":"u03_l01_q144","lesson_id":"u03_l01","difficulty":"medium","prompt":"لماذا يُعد الاقتصاد في النفقة بين البخل والإسراف من صفات عباد الرحمن؟","options":[{"id":"o3","text":"لأن الإسراف دليل دائم على الكرم"},{"id":"o2","text":"لأنه يمنع إعانة المحتاجين"},{"id":"o4","text":"لأن البخل مطلوب شرعًا"},{"id":"o1","text":"لأنه يحفظ المال ويضعه في وجوهه النافعة دون تبذير أو إمساك مذموم"}],"correct_id":"o1","explanation":"شرح الدرس أثر الاعتدال بين الإفراط في الإنفاق والإقتار.","page":95},{"id":"u03_l01_q147","lesson_id":"u03_l01","difficulty":"medium","prompt":"ما الذي تعبّر عنه دعوة عباد الرحمن أن تكون أزواجهم وذرياتهم «قرة أعين»؟","options":[{"id":"o1","text":"طلب الهداية والصلاح للأهل والذرية"},{"id":"o2","text":"طلب كثرة المال بأي طريق"},{"id":"o3","text":"إهمال تربية الأبناء"},{"id":"o4","text":"حصر الصلاح بالفرد وحده"}],"correct_id":"o1","explanation":"شرح الدرس سؤال العبد الصلاح لأسرته وما يسره في الدين والدنيا.","page":97},{"id":"u03_l01_q153","lesson_id":"u03_l01","difficulty":"hard","prompt":"ما دلالة ذكر السجود في سياق الحديث عن عبادة الليل مع أن السجود يأتي بعد القيام؟","options":[{"id":"o3","text":"جعل السجود خارج الصلاة دائمًا"},{"id":"o4","text":"أن ترتيب أفعال الصلاة غير معروف"},{"id":"o2","text":"نفي قيمة الصلاة في قيام الليل"},{"id":"o1","text":"إظهار منزلته بوصفه من أعظم صور الخضوع لله"}],"correct_id":"o1","explanation":"نبّه شرح الدرس إلى منزلة السجود في إظهار الخضوع والعبودية.","page":94},{"id":"u03_l01_q154","lesson_id":"u03_l01","difficulty":"medium","prompt":"كيف يختلف ضرر الإسراف عن ضرر الإقتار وفق شرح صفات عباد الرحمن؟","options":[{"id":"o4","text":"لا أثر لأي منهما في احتياجات الأسرة"},{"id":"o2","text":"الإسراف يحفظ المال والإقتار يزيد التكافل تلقائيًا"},{"id":"o1","text":"الإسراف يستنزف المال والإقتار يمنع الانتفاع به والإنفاق على مستحقيه"},{"id":"o3","text":"كلاهما يحقق أفضل توزيع للمال دائمًا"}],"correct_id":"o1","explanation":"قارن الكتاب بين استنفاد المال بالإسراف وحرمان مستحقيه بالإقتار.","page":95},{"id":"u03_l01_q155","lesson_id":"u03_l01","difficulty":"medium","prompt":"إذا مرّ طالب بمجلس كلام لا فائدة فيه ولم يشارك فيه، فأي معنى قرآني طبّقه؟","options":[{"id":"o2","text":"طلب حضور تلك المجالس بقصد إثارة الفتنة"},{"id":"o4","text":"الانتفاع بالمال دون اعتدال"},{"id":"o3","text":"الشهادة على الناس بما لم يقع"},{"id":"o1","text":"المرور باللغو مع حفظ الكرامة وعدم الانجرار إليه"}],"correct_id":"o1","explanation":"شرح الدرس ترك مجالس اللغو وعدم الاندفاع إلى ما فيها.","page":96},{"id":"u03_l01_q157","lesson_id":"u03_l01","difficulty":"medium","prompt":"لماذا يتجاوز دعاء عباد الرحمن للأزواج والذرية مجرد طلب سعادة فردية؟","options":[{"id":"o4","text":"لأنه يرفض دعوة غير الأقارب إلى الخير"},{"id":"o2","text":"لأنه يقتصر على زيادة الثروة الشخصية"},{"id":"o1","text":"لأنه يتضمن صلاح الأسرة والقدوة الصالحة للآخرين"},{"id":"o3","text":"لأنه يمنع المسؤولية تجاه الأقربين"}],"correct_id":"o1","explanation":"فسّر الدرس الدعاء بحب الخير للأهل والرغبة في القدوة للناس.","page":97},{"id":"u03_l01_q166","lesson_id":"u03_l01","difficulty":"medium","prompt":"لماذا يعد تقديم شهادة زور لأخذ حق شخص آخر مناقضًا لصفات عباد الرحمن؟","options":[{"id":"o1","text":"لأنها شهادة كاذبة تضيّع الحقوق وتؤدي إلى الباطل"},{"id":"o2","text":"لأنها وسيلة مأذون بها لحل الخصومات"},{"id":"o3","text":"لأنها تضمن العدل بين الأطراف"},{"id":"o4","text":"لأن الخطأ فيها يتعلق بنوع الخط فقط"}],"correct_id":"o1","explanation":"شرح الدرس أن شهادة الزور كذب يؤدي إلى أكل حقوق الناس وضياعها.","page":96},{"id":"u03_l01_q168","lesson_id":"u03_l01","difficulty":"medium","prompt":"أي معنى تضمنه استقبال الملائكة لعباد الرحمن في جزائهم؟","options":[{"id":"o4","text":"انتهاء الجزاء بعودة الحساب"},{"id":"o3","text":"إعادتهم إلى الدنيا للعمل من جديد"},{"id":"o1","text":"التكريم والتحية والترحيب بهم"},{"id":"o2","text":"العتاب على تواضعهم"}],"correct_id":"o1","explanation":"ذكر الكتاب احترام الملائكة وترحيبهم من جزاء عباد الرحمن.","page":97},{"id":"u03_l01_q173","lesson_id":"u03_l01","difficulty":"easy","prompt":"كيف يواجه عباد الرحمن الإساءة اللفظية من الجاهلين بحسب الآيات؟","options":[{"id":"o2","text":"بتبادل الألفاظ الجارحة"},{"id":"o3","text":"بنشر الإساءة بين الناس"},{"id":"o4","text":"بالانتقام فورًا ممن يتكلم"},{"id":"o1","text":"بالإعراض والقول الطيب دون مقابلة الإساءة بمثلها"}],"correct_id":"o1","explanation":"ذكر الكتاب الحلم والإعراض عن الجاهلين والرد بالكلام الحسن.","page":94},{"id":"u03_l01_q182","lesson_id":"u03_l01","difficulty":"hard","prompt":"إذا واجه شخصًا جاهلًا أساء إليه، كيف ينسجم الرد الهادئ مع صفات عباد الرحمن؟","options":[{"id":"o2","text":"يجعل الإهانة مبررًا للإساءة المتبادلة"},{"id":"o4","text":"يلغي واجب حسن الخلق مع الآخرين"},{"id":"o3","text":"يعني إقرار كل كلام باطل بأنه صحيح"},{"id":"o1","text":"يصون كرامته ويمنع الانجرار إلى السفه والخصومة"}],"correct_id":"o1","explanation":"ربط الدرس تعاملهم مع الجاهلين بالحلم وترك مقابلة الإساءة بمثلها.","page":94},{"id":"u03_l01_q183","lesson_id":"u03_l01","difficulty":"medium","prompt":"أي نمط في الإنفاق يعكس الصفة المقصودة بقول الآيات إن إنفاقهم يكون قوامًا؟","options":[{"id":"o4","text":"حصر العطاء في إظهار المكانة"},{"id":"o1","text":"نفقة متوازنة بين البخل والإسراف"},{"id":"o3","text":"إنفاق كل المال دون النظر إلى حقوق الأسرة"},{"id":"o2","text":"منع الإنفاق على كل حاجة ضرورية"}],"correct_id":"o1","explanation":"شرح الكتاب التوازن في الإنفاق والابتعاد عن التقتير والتبذير.","page":95},{"id":"u03_l01_q185","lesson_id":"u03_l01","difficulty":"medium","prompt":"لماذا لا تكون التوبة مجرد نطق بالاستغفار إذا كان الذنب متعلقًا بحق إنسان؟","options":[{"id":"o3","text":"لأن العودة إلى المعصية شرط لقبولها"},{"id":"o1","text":"لأن التوبة تقتضي رد الحق لصاحبه مع الندم والإقلاع"},{"id":"o2","text":"لأن الحقوق تسقط بمجرد نسيان صاحبها"},{"id":"o4","text":"لأن رد الحقوق يناقض طلب المغفرة"}],"correct_id":"o1","explanation":"عدد الدرس رد الحقوق إلى أصحابها بين شروط التوبة الصادقة.","page":96},{"id":"u03_l01_q187","lesson_id":"u03_l01","difficulty":"medium","prompt":"ما المعنى التربوي لدعاء المؤمن أن يكون أهل بيته قرة عين له؟","options":[{"id":"o4","text":"استغناؤه عن حسن القدوة في المنزل"},{"id":"o2","text":"رغبته في إشغالهم بالترف وحده"},{"id":"o3","text":"اعتماده على صلاحه وترك نصح أسرته"},{"id":"o1","text":"رغبته في هدايتهم وصلاحهم لا في منفعة شخصية فقط"}],"correct_id":"o1","explanation":"فسر الدرس قرة العين بما يسر النفس من صلاح الأهل والأبناء.","page":97},{"id":"u03_l02_q091","lesson_id":"u03_l02","difficulty":"medium","prompt":"زوجان تعذّر إصلاح الخلاف المستحكم بينهما؛ أي غاية شرعية تُفهم من إباحة الطلاق عند توافر أسبابه؟","options":[{"id":"o4","text":"جعل التفريق غاية بحد ذاته"},{"id":"o3","text":"إسقاط حقوق الأطفال بعد الانفصال"},{"id":"o2","text":"اعتبار كل خلاف سببًا للطلاق الفوري"},{"id":"o1","text":"رفع الضرر عند تعذّر استمرار الحياة الزوجية"}],"correct_id":"o1","explanation":"ذكر الدرس تشريع الطلاق عند استحكام الخلاف وتعذر الإصلاح والتوفيق.","page":101},{"id":"u03_l02_q109","lesson_id":"u03_l02","difficulty":"hard","prompt":"بعد طلقة أولى وانتهاء العدة دون مراجعة، أراد الزوجان العودة؛ ما التصرف الموافق للدرس؟","options":[{"id":"o4","text":"معاملة الحالة باعتبارها طلقة ثالثة دائمًا"},{"id":"o2","text":"إرجاعها دون رضا أو عقد بعد انتهاء العدة"},{"id":"o3","text":"اعتبار العلاقة قائمة تلقائيًا"},{"id":"o1","text":"عقد ومهر جديدان برضا الزوجة"}],"correct_id":"o1","explanation":"تعرف الصفحة 103 البينونة الصغرى وحكم العودة بعد انتهاء العدة.","page":103},{"id":"u03_l02_q117","lesson_id":"u03_l02","difficulty":"medium","prompt":"ما الإجراء الذي يذكره صندوق القانون الأردني بشأن الطلاق والرجعة؟","options":[{"id":"o2","text":"الاكتفاء بإخبار الجيران"},{"id":"o3","text":"تسجيل الرجعة لدى متجر خاص"},{"id":"o1","text":"تسجيل الواقعة في المحكمة الشرعية"},{"id":"o4","text":"اعتبار التسجيل أمرًا لا صلة له بالقانون"}],"correct_id":"o1","explanation":"ينص صندوق الكتاب على إلزام الزوج بتسجيل الطلاق والرجعة في المحكمة الشرعية.","page":104},{"id":"u03_l02_q127","lesson_id":"u03_l02","difficulty":"hard","prompt":"أي شرط إضافي يجب تحققه قبل عودة المرأة إلى زوجها الأول بعد البينونة الكبرى؟","options":[{"id":"o4","text":"أن يعقد الزوج الأول عليها فور الطلقة الثالثة"},{"id":"o1","text":"زواج صحيح بزوج آخر مع الدخول ثم انتهاء ذلك الزواج والعدة"},{"id":"o3","text":"أن يراجعها الزوج الأول في العدة السابقة مباشرة"},{"id":"o2","text":"أن يكرر الزوج الأول اعتذاره فقط"}],"correct_id":"o1","explanation":"بين الدرس ضوابط العودة بعد البينونة الكبرى بعقد جديد وفق الشروط المذكورة.","page":103},{"id":"u03_l02_q133","lesson_id":"u03_l02","difficulty":"medium","prompt":"طلقت امرأة طلقة أولى بعد الدخول ولا تزال في العدة؛ أي إجراء للرجعة يوافق قسم الطلاق المذكور؟","options":[{"id":"o3","text":"انتظار انتهاء العدة لتكون الرجعة بلا عقد"},{"id":"o4","text":"منع الرجعة في جميع الأحوال"},{"id":"o2","text":"اشتراط زواجها بآخر أولًا"},{"id":"o1","text":"مراجعتها أثناء العدة دون عقد ومهر جديدين"}],"correct_id":"o1","explanation":"شرح الدرس الطلاق الرجعي وإمكان الرجعة في العدة دون عقد جديد.","page":102},{"id":"u03_l02_q135","lesson_id":"u03_l02","difficulty":"medium","prompt":"انتهت عدة مطلقة بطلقة أولى دون رجعة؛ فما الوصف الصحيح لإمكان العودة؟","options":[{"id":"o4","text":"تُلغى الطلقة السابقة من كل وجه"},{"id":"o2","text":"عودة تلقائية دون موافقتها"},{"id":"o3","text":"يشترط زواجها برجل آخر أولًا"},{"id":"o1","text":"لا عودة إلا برضاها وعقد ومهر جديدين"}],"correct_id":"o1","explanation":"هذا من أمثلة البينونة الصغرى في شرح الكتاب.","page":103},{"id":"u03_l02_q136","lesson_id":"u03_l02","difficulty":"hard","prompt":"ما الشرط الذي لا يوجد في العودة بعد البينونة الصغرى ويوجد بعد البينونة الكبرى؟","options":[{"id":"o4","text":"التأكد من انتهاء العدة الحالية"},{"id":"o2","text":"رضا المرأة بالعقد الجديد"},{"id":"o1","text":"زواج صحيح بزوج آخر ثم انتهاء تلك العلاقة والعدة"},{"id":"o3","text":"دفع مهر بعقد جديد"}],"correct_id":"o1","explanation":"شرح الدرس اشتراط زواج آخر صحيح في البينونة الكبرى دون الصغرى.","page":103},{"id":"u03_l02_q142","lesson_id":"u03_l02","difficulty":"medium","prompt":"لماذا لا يُعد الطلاق وسيلة مقبولة للإضرار بالزوجة أو حرمانها من حقوقها؟","options":[{"id":"o4","text":"لأن الحقوق تسقط بمجرد الخلاف"},{"id":"o3","text":"لأن إلحاق الضرر بالآخرين مقصد للزواج"},{"id":"o1","text":"لأن الشرع منع الطلاق التعسفي القائم على الإضرار والظلم"},{"id":"o2","text":"لأن الطلاق لا أثر له في الحقوق"}],"correct_id":"o1","explanation":"ينص الدرس على منع قصد الإضرار وذكر التعويض في القانون عند الطلاق التعسفي.","page":101},{"id":"u03_l02_q144","lesson_id":"u03_l02","difficulty":"medium","prompt":"طلّق رجل زوجته المدخول بها طلقة أولى ولم تنقضِ عدتها؛ أي أثر يميّز الطلاق الرجعي؟","options":[{"id":"o3","text":"ضرورة زواجها بآخر قبل الرجعة"},{"id":"o4","text":"سقوط واجبات العلاقة كلها فورًا"},{"id":"o2","text":"انتهاء حق الرجعة في كل الأحوال"},{"id":"o1","text":"إمكان مراجعتها في العدة دون عقد ومهر جديدين"}],"correct_id":"o1","explanation":"عرّف الدرس الرجعي بما يتيح المراجعة أثناء العدة دون عقد أو مهر جديد.","page":102},{"id":"u03_l02_q153","lesson_id":"u03_l02","difficulty":"medium","prompt":"بعد طلقة أولى رجعية، ما أثر مرور عدة الزوجة دون أن يراجعها زوجها؟","options":[{"id":"o4","text":"تعود الزوجية دون رضا الطرفين ولا عقد"},{"id":"o3","text":"تتحول تلقائيًا إلى طلقة ثالثة"},{"id":"o2","text":"تبقى الرجعة ممكنة دون عقد إلى غير نهاية"},{"id":"o1","text":"تصير الفرقة بائنة بينونة صغرى ويحتاج الرجوع إلى عقد جديد برضاها"}],"correct_id":"o1","explanation":"فرّق الكتاب بين الرجعي أثناء العدة والبائن بينونة صغرى بعد انقضائها.","page":103},{"id":"u03_l02_q181","lesson_id":"u03_l02","difficulty":"medium","prompt":"ما الذي يجعل الطلاق التعسفي مختلفًا عن الطلاق عند تعذر الصلح؟","options":[{"id":"o3","text":"وقوعه وفق ضوابط تحفظ الحقوق"},{"id":"o2","text":"وقوعه بعد استحكام الخلاف مع محاولة الإصلاح"},{"id":"o1","text":"وقوعه للإضرار أو بلا سبب مقبول شرعًا"},{"id":"o4","text":"وقوعه بعد دراسة حال الأسرة وأبنائها"}],"correct_id":"o1","explanation":"ميز الدرس بين مشروعية الطلاق عند دواعيه وتحريم قصد الإضرار والتعسف.","page":101},{"id":"u03_l02_q183","lesson_id":"u03_l02","difficulty":"medium","prompt":"ما الإجراء الذي ينسجم مع مقصد الإصلاح قبل إنهاء الزواج عند نشوب نزاع شديد؟","options":[{"id":"o1","text":"طلب التحكيم والسعي إلى التوفيق بين الزوجين"},{"id":"o4","text":"إغلاق باب الحوار دون محاولة"},{"id":"o3","text":"البدء بحرمان الأبناء من حقوقهم"},{"id":"o2","text":"إفشاء الأسرار الشخصية على الملأ"}],"correct_id":"o1","explanation":"استشهد الدرس بآيات حسن المعاشرة والتحكيم قبل تعذر الصلح.","page":102},{"id":"u03_l02_q185","lesson_id":"u03_l02","difficulty":"medium","prompt":"زوج طلّق زوجته طلقة أولى بعد الدخول وما تزال في عدتها؛ ما الصفة التي تميز هذا الطلاق؟","options":[{"id":"o2","text":"تحريم أي رجعة إلى الأبد"},{"id":"o4","text":"انتهاء كل علاقة فورًا بلا عدّة"},{"id":"o1","text":"إمكان الرجعة ضمن العدّة دون عقد جديد"},{"id":"o3","text":"الحاجة إلى زواجها من رجل آخر قبل الرجعة"}],"correct_id":"o1","explanation":"يفرق الدرس بين الطلاق الرجعي والبائن بحسب إمكان الرجعة وعدد الطلقات.","page":103},{"id":"u03_l02_q186","lesson_id":"u03_l02","difficulty":"medium","prompt":"أي سلوك بعد الطلاق ينسجم مع آداب الشريعة إذا كان بين الزوجين أطفال؟","options":[{"id":"o4","text":"نشر تفاصيل الحياة الزوجية السابقة"},{"id":"o1","text":"حفظ حقوق الأطفال ورعايتهم بعيدًا عن الخلاف"},{"id":"o3","text":"التوقف عن النفقة الواجبة لمجرد الخصومة"},{"id":"o2","text":"استعمال الأبناء وسيلة للضغط على الآخر"}],"correct_id":"o1","explanation":"أبرز الكتاب رعاية الأبناء والستر وحسن المعاملة وأداء الحقوق بعد الطلاق.","page":104},{"id":"u03_l02_q187","lesson_id":"u03_l02","difficulty":"hard","prompt":"لماذا يلزم القانون الأردني بتسجيل وقوع الطلاق والرجعة في المحكمة الشرعية؟","options":[{"id":"o3","text":"لإلغاء حق الطفل في الرعاية"},{"id":"o2","text":"لجعل النشر الإعلامي شرطًا لصحة الزواج"},{"id":"o1","text":"لحفظ الحقوق وتوثيق ما يترتب على تغيّر العلاقة الزوجية"},{"id":"o4","text":"لمنع النظر في النزاعات الأسرية نهائيًا"}],"correct_id":"o1","explanation":"ذكر الكتاب إلزام الزوج بتسجيل وقائع الطلاق والرجعة في المحكمة الشرعية.","page":104},{"id":"u03_l03_q096","lesson_id":"u03_l03","difficulty":"medium","prompt":"خلال عدة الطلاق الرجعي، ما سبب دعوة المرأة للاعتداد في بيت الزوجية؟","options":[{"id":"o4","text":"منع حق الإرث بين الزوجين"},{"id":"o2","text":"قطع كل صلة زوجية فورًا"},{"id":"o1","text":"إتاحة فرصة الرجعة واستعادة الحياة الأسرية"},{"id":"o3","text":"اعتبار الطلاق بائنًا من أول لحظة"}],"correct_id":"o1","explanation":"ذكر الكتاب استمرار العصمة وإمكان الرجعة حكمتين للبقاء في بيت الزوجية.","page":110},{"id":"u03_l03_q105","lesson_id":"u03_l03","difficulty":"medium","prompt":"لماذا لا يلغي تقدم الفحوص الطبية وجوب العدة؟","options":[{"id":"o2","text":"لأن الطب لا يبحث الحمل مطلقًا"},{"id":"o3","text":"لأن المقصد الوحيد هو معرفة السكن"},{"id":"o1","text":"لأن العدة حكم تعبدي له حكم متعددة"},{"id":"o4","text":"لأن العدة لا تتعلق بأحكام شرعية"}],"correct_id":"o1","explanation":"نبه الكتاب إلى أن إمكانية إثبات براءة الرحم لا تبطل التعبد بالعدة.","page":108},{"id":"u03_l03_q107","lesson_id":"u03_l03","difficulty":"medium","prompt":"ما الذي يميز توارث الزوجين في عدة طلاق رجعي عن عدة طلاق بائن؟","options":[{"id":"o3","text":"يثبت التوارث في البائن دون الرجعي"},{"id":"o2","text":"ينقطع التوارث في الرجعي وحده"},{"id":"o4","text":"لا علاقة للتوارث باستمرار الزوجية"},{"id":"o1","text":"يبقى التوارث في الرجعي ولا يكون في البائن"}],"correct_id":"o1","explanation":"يربط الدرس الإرث ببقاء رباط الزوجية في الرجعي.","page":110},{"id":"u03_l03_q113","lesson_id":"u03_l03","difficulty":"medium","prompt":"لماذا لا تتوقف عدة المتوفى عنها زوجها غير الحامل على حصول الدخول؟","options":[{"id":"o1","text":"لأن الحكم في الجدول يشمل الحالتين"},{"id":"o4","text":"لأن سبب العدة هو عدد الأولاد فقط"},{"id":"o3","text":"لأن العدة لا تشرع عند الوفاة"},{"id":"o2","text":"لأن العدة تنتهي دائمًا فور الوفاة"}],"correct_id":"o1","explanation":"نص جدول العدة بسبب الوفاة على شمول غير الحامل للمدخول بها وغير المدخول بها.","page":109},{"id":"u03_l03_q116","lesson_id":"u03_l03","difficulty":"medium","prompt":"ما حالة الاستثناء التي تسمح للمعتدة من وفاة زوجها بالمبيت عند أهلها؟","options":[{"id":"o1","text":"إذا كانت لا تأمن على نفسها وهي وحدها في بيت الزوجية"},{"id":"o3","text":"إذا أرادت إلغاء الحداد نهائيًا"},{"id":"o4","text":"إذا انتهى يوم عملها مبكرًا"},{"id":"o2","text":"إذا رغبت بتغيير المكان كل ليلة دون حاجة"}],"correct_id":"o1","explanation":"أجاز الدرس المبيت عند الأهل حال عدم الأمن أو الوحدة دون محرم في البيت.","page":111},{"id":"u03_l03_q117","lesson_id":"u03_l03","difficulty":"medium","prompt":"ما سبب بقاء التوارث في عدة الطلاق الرجعي بخلاف البائن؟","options":[{"id":"o4","text":"اختلاف عدد أشهر السنة"},{"id":"o2","text":"انتفاء رابطة الزوجية في النوعين"},{"id":"o3","text":"وجود عقد جديد تلقائي في البائن"},{"id":"o1","text":"استمرار رباط الزوجية حكمًا في الرجعي وانتهاؤه في البائن"}],"correct_id":"o1","explanation":"فرّق الدرس في التوارث تبعًا لبقاء الرابطة في الرجعي وانتهائها في البائن.","page":110},{"id":"u03_l03_q119","lesson_id":"u03_l03","difficulty":"hard","prompt":"أي مقارنة صحيحة بين المطلقة قبل الدخول والمتوفى عنها زوجها قبل الدخول إذا لم تكن حاملًا؟","options":[{"id":"o2","text":"كلتاهما تعتدان ثلاث حيضات"},{"id":"o4","text":"المطلقة تعتد أربعة أشهر وعشرة أيام والمتوفى عنها لا تعتد"},{"id":"o3","text":"كلتاهما لا عدة عليهما"},{"id":"o1","text":"المطلقة لا عدة عليها والمتوفى عنها زوجها تعتد أربعة أشهر وعشرة أيام"}],"correct_id":"o1","explanation":"جمع الكتاب بين نفي عدة المطلقة قبل الدخول ووجوب عدة الوفاة لغير الحامل مطلقًا.","page":108},{"id":"u03_l03_q131","lesson_id":"u03_l03","difficulty":"medium","prompt":"ما حكم تخصيص الثوب الأسود وحده للمرأة في حدادها على زوجها وفق الإثراء؟","options":[{"id":"o3","text":"يجب الثوب الأحمر عند الخروج للحاجة"},{"id":"o4","text":"يقتصر الحداد على تغيير لون الحذاء"},{"id":"o1","text":"لا يشترط لون معين من الثياب في الحداد"},{"id":"o2","text":"يجب السواد في جميع الملابس دون استثناء"}],"correct_id":"o1","explanation":"نص الإثراء على تجنب الزينة في الحداد وأنه لا يشترط لون محدد مثل السواد.","page":111},{"id":"u03_l03_q146","lesson_id":"u03_l03","difficulty":"hard","prompt":"لماذا يبقى التوارث قائمًا إذا توفي أحد الزوجين أثناء عدة الطلاق الرجعي؟","options":[{"id":"o2","text":"لأن العدة تسقط كل حقوق الزوجين"},{"id":"o4","text":"لأن التوارث لا يتعلق بالزوجية"},{"id":"o1","text":"لأن رابطة الزوجية قائمة حكمًا في مدة العدة الرجعية"},{"id":"o3","text":"لأن الطلاق البائن والرجعي متماثلان في الإرث"}],"correct_id":"o1","explanation":"ينص الدرس على ثبوت الإرث بين الزوجين في العدة الرجعية بخلاف البائن.","page":110},{"id":"u03_l03_q157","lesson_id":"u03_l03","difficulty":"medium","prompt":"لماذا تُلزم المطلقة رجعيًا بالاعتداد في بيت الزوجية وفق الشرح؟","options":[{"id":"o2","text":"لأن الطلاق الرجعي ينهي الزواج فورًا دون فرصة للمراجعة"},{"id":"o3","text":"لأنها لا تملك أي حقوق في العدة"},{"id":"o1","text":"لبقاء الرابطة الزوجية وإتاحة فرصة الإصلاح والرجعة"},{"id":"o4","text":"لإلغاء كل اتصال بالزوج أثناء العدة"}],"correct_id":"o1","explanation":"نص الكتاب على الاعتداد في بيت الزوجية لما في ذلك من إمكان الرجعة.","page":110},{"id":"u03_l03_q163","lesson_id":"u03_l03","difficulty":"medium","prompt":"أي ترتيب صحيح لأحكام عدة المطلقة قبل الدخول والمطلقة غير الحائض بعد الدخول والمطلقة الحامل؟","options":[{"id":"o3","text":"ثلاثة أشهر ثم لا عدة ثم أربعون يومًا"},{"id":"o2","text":"ثلاث حيضات ثم أربعة أشهر ثم عشرون يومًا"},{"id":"o4","text":"أربعة أشهر وعشرة أيام لجميع الحالات"},{"id":"o1","text":"لا عدة ثم ثلاثة أشهر قمرية ثم حتى وضع الحمل"}],"correct_id":"o1","explanation":"يميز جدول الدرس بين سقوط العدة قبل الدخول وعدة غير الحائض بعد الدخول وانتهاء عدة الحامل بوضع الحمل.","page":109},{"id":"u03_l03_q165","lesson_id":"u03_l03","difficulty":"medium","prompt":"بماذا يتميز ميراث الزوجين خلال عدة الطلاق الرجعي عما بعد الطلاق البائن؟","options":[{"id":"o4","text":"يصبح الميراث مشروطًا بمدة الخطبة"},{"id":"o2","text":"ينقطع التوارث في الرجعي فقط"},{"id":"o3","text":"يتساوى الحكمان دون فرق"},{"id":"o1","text":"يبقى التوارث في الرجعي ولا يكون في البائن بعد انتهاء الزوجية"}],"correct_id":"o1","explanation":"ذكر الدرس بقاء حق الإرث في الرجعي وعدم التوارث في الطلاق البائن.","page":110},{"id":"u03_l03_q166","lesson_id":"u03_l03","difficulty":"hard","prompt":"ما الوصف الصحيح لطلب الزواج من معتدة وفاة قبل انتهاء عدتها؟","options":[{"id":"o1","text":"يجوز التعريض بالخطبة لا التصريح بها ولا العقد"},{"id":"o3","text":"تحرم حتى الإشارة غير الصريحة في كل ظرف"},{"id":"o4","text":"يجوز التصريح بالخطبة دون انتظار"},{"id":"o2","text":"يجوز عقد الزواج فورًا إذا قبلت"}],"correct_id":"o1","explanation":"فرّق الكتاب بين التعريض الجائز في عدة الوفاة والتصريح الممنوع.","page":110},{"id":"u03_l03_q174","lesson_id":"u03_l03","difficulty":"medium","prompt":"توفي رجل عن زوجة غير حامل ولم يدخل بها؛ فما عدة الوفاة بحسب الجدول؟","options":[{"id":"o2","text":"لا عدة عليها لعدم الدخول"},{"id":"o1","text":"أربعة أشهر وعشرة أيام قمرية"},{"id":"o3","text":"ثلاثة قروء"},{"id":"o4","text":"ثلاثة أشهر قمرية فقط"}],"correct_id":"o1","explanation":"يبين الجدول أن عدة وفاة الزوج لغير الحامل أربعة أشهر وعشرة أيام ولو لم يحدث الدخول.","page":109},{"id":"u03_l03_q176","lesson_id":"u03_l03","difficulty":"medium","prompt":"ما أثر الطلاق البائن على توارث الزوجين إذا توفي أحدهما أثناء العدة؟","options":[{"id":"o3","text":"يصبح التوارث مضاعفًا في هذه الحالة"},{"id":"o2","text":"التوارث قائم دائمًا كالمطلقة الرجعية"},{"id":"o4","text":"لا يتوقف على نوع الطلاق مطلقًا"},{"id":"o1","text":"لا توارث بينهما لانتهاء العلاقة الزوجية"}],"correct_id":"o1","explanation":"فرق الكتاب بين بقاء التوارث في عدة الرجعي وانقطاعه في البائن.","page":110},{"id":"u03_l03_q185","lesson_id":"u03_l03","difficulty":"medium","prompt":"خلال عدة طلاق بائن بينونة صغرى، ما حكم تقدم رجل جديد لخطبة المرأة تصريحًا؟","options":[{"id":"o4","text":"يصبح من حقه إعادتها إلى زوجها السابق"},{"id":"o1","text":"يحرم التصريح بخطبتها خلال العدة"},{"id":"o3","text":"يجوز العقد عليها قبل انتهاء عدتها"},{"id":"o2","text":"تنعقد الخطبة تلقائيًا دون رضاها"}],"correct_id":"o1","explanation":"نص الكتاب على حرمة خطبة المعتدة من طلاق رجعي أو بائن خلال العدة، وميّز حالة عدة الوفاة في التعريض.","page":110},{"id":"u03_l03_q187","lesson_id":"u03_l03","difficulty":"medium","prompt":"ما الفارق بين تصريح الرجل برغبته في الزواج والتعريض بذلك أثناء عدة الوفاة؟","options":[{"id":"o4","text":"كلاهما يعني إتمام عقد الزواج فورًا"},{"id":"o2","text":"التعريض عقد زواج ملزم والتصريح مجرد دعاء"},{"id":"o3","text":"التصريح يعني الزيارة والتعريض يعني النفقة"},{"id":"o1","text":"التصريح طلب صريح والتعريض كلام غير مباشر"}],"correct_id":"o1","explanation":"فرق الدرس بين عبارة واضحة تكشف المراد وعبارة تلمح إليه.","page":110},{"id":"u03_l04_q096","lesson_id":"u03_l04","difficulty":"medium","prompt":"كتابة المرء ما له وما عليه من حقوق للآخرين في وصية تحقق أي غاية وردت في التوسع؟","options":[{"id":"o3","text":"إسقاط حقوق أصحابها"},{"id":"o4","text":"منع الورثة من الاطلاع عليها"},{"id":"o2","text":"التحلل من أداء الديون"},{"id":"o1","text":"توثيق الحقوق وعدم تضييعها"}],"correct_id":"o1","explanation":"ندب الكتاب كتابة الوصية لبيان الحقوق والالتزامات.","page":117},{"id":"u03_l04_q106","lesson_id":"u03_l04","difficulty":"medium","prompt":"ما الحكم الأصلي لوصية خص بها الموصي أحد الورثة دون موافقة الآخرين بعد وفاته؟","options":[{"id":"o3","text":"تبطل جميع الوصايا الخيرية بسببها"},{"id":"o1","text":"لا تنفذ إلا بإجازة جميع الورثة"},{"id":"o4","text":"تتحول إلى ميراث إضافي واجب له"},{"id":"o2","text":"تنفذ بمجرد رغبة الموصي دون اعتبار للورثة"}],"correct_id":"o1","explanation":"قرر الكتاب شرط موافقة الورثة للوصية لوارث.","page":116},{"id":"u03_l04_q117","lesson_id":"u03_l04","difficulty":"medium","prompt":"ما قيمة كتابة الحقوق والديون في وصية إلى جانب التبرع الخيري؟","options":[{"id":"o3","text":"إخفاء الالتزامات عن الورثة"},{"id":"o4","text":"استبدال أداء الحقوق بالتبرع الاختياري"},{"id":"o2","text":"إسقاط الديون عن الموصي تلقائيًا"},{"id":"o1","text":"حفظ حقوق الناس ومنع ضياع الالتزامات"}],"correct_id":"o1","explanation":"أرشد التوسع إلى كتابة ما للإنسان وما عليه من حقوق للآخرين.","page":117},{"id":"u03_l04_q118","lesson_id":"u03_l04","difficulty":"hard","prompt":"أوصى رجل بربع ماله لأحد ورثته دون إجازة بقية الورثة بعد موته؛ أي حكم ينطبق؟","options":[{"id":"o2","text":"تنفذ لأن مقدارها دون الثلث فقط"},{"id":"o4","text":"تنفذ إذا وافق الموصى له وحده"},{"id":"o3","text":"تلغى قاعدة الوصية للوارث إذا كانت مكتوبة"},{"id":"o1","text":"لا تنفذ الوصية للوارث دون موافقة جميع الورثة"}],"correct_id":"o1","explanation":"قيد الدرس الوصية للوارث بإجازة جميع الورثة بعد موت الموصي مهما كان المقدار.","page":116},{"id":"u03_l04_q122","lesson_id":"u03_l04","difficulty":"medium","prompt":"ما الحكمة التي يبرزها دعم طالب علم فقير من مال موصى به بعد الوفاة؟","options":[{"id":"o4","text":"حرمان الأقارب من الحقوق الثابتة"},{"id":"o2","text":"إلغاء نصيب الورثة بغير ضابط"},{"id":"o3","text":"تقييد العلم بأصحاب الأموال"},{"id":"o1","text":"الإسهام في التكافل ونشر الخير بعد الموت"}],"correct_id":"o1","explanation":"ذكر الدرس سد حاجة المحتاجين ونشر الخير من حكم الوصية.","page":115},{"id":"u03_l04_q132","lesson_id":"u03_l04","difficulty":"medium","prompt":"خصّص إنسان بعد وفاته جزءًا من ماله لكفالة أيتام؛ فأي حكمة من الوصية تتحقق؟","options":[{"id":"o3","text":"إلزام الأيتام بنفقة عكسية"},{"id":"o1","text":"التكافل الاجتماعي وسد حاجة المحتاجين"},{"id":"o4","text":"تعطيل عمل المؤسسات الخيرية"},{"id":"o2","text":"حرمان الورثة عمدًا"}],"correct_id":"o1","explanation":"يذكر الدرس أن الوصية تعزز التكافل وتدعم المحتاجين.","page":115},{"id":"u03_l04_q136","lesson_id":"u03_l04","difficulty":"medium","prompt":"ترك رجل وصية لوارث بعد وفاته، فما شرط تنفيذها بحسب النص؟","options":[{"id":"o3","text":"اكتفاء الوارث بالمطالبة بها"},{"id":"o4","text":"اشتراط مضي سنة على الوصية"},{"id":"o2","text":"استغناء الوارث عن نصيبه الأصلي فقط"},{"id":"o1","text":"موافقة جميع الورثة بعد الوفاة"}],"correct_id":"o1","explanation":"بيّن الكتاب أن الوصية لوارث لا تنفذ إلا بموافقة جميع الورثة بعد الموت.","page":116},{"id":"u03_l04_q137","lesson_id":"u03_l04","difficulty":"medium","prompt":"شخص عدّل وصيته وهو على قيد الحياة؛ أي حكم يجعل فعله ممكنًا؟","options":[{"id":"o2","text":"بطلان كل تعديل بعد كتابة الوصية"},{"id":"o3","text":"وجوب التنازل عن المال فورًا"},{"id":"o1","text":"جواز الرجوع في الوصية أو تغييرها قبل الوفاة"},{"id":"o4","text":"انتقال ملك المال للموصى له فورًا"}],"correct_id":"o1","explanation":"يجيز الدرس الرجوع عن الوصية وتعديلها قبل الموت.","page":116},{"id":"u03_l04_q140","lesson_id":"u03_l04","difficulty":"hard","prompt":"ما الذي يميز الوصية بالنصح لأهل الموصي عن الوصية المالية؟","options":[{"id":"o4","text":"الثانية تقتصر على أداء الصلاة"},{"id":"o3","text":"الأولى لا تتعلق بالقيم"},{"id":"o1","text":"الأولى توجيه إلى الخير كصلة الرحم والصلاة لا تمليك مال بعد الوفاة"},{"id":"o2","text":"كلتاهما تعني بيع الأموال قبل الموت"}],"correct_id":"o1","explanation":"ذكر الإثراء استحباب الوصية للأهل بالمحافظة على الخير والواجبات.","page":117},{"id":"u03_l04_q144","lesson_id":"u03_l04","difficulty":"medium","prompt":"أوصى شخص بأكثر من ثلث ماله؛ ما وضع الجزء الزائد وفق الضابط المدرسي؟","options":[{"id":"o1","text":"تنفيذه متوقف على موافقة الورثة"},{"id":"o4","text":"يُلغى جميع المال الموروث"},{"id":"o3","text":"يُقدّم على الديون مهما كانت"},{"id":"o2","text":"ينفذ حتمًا دون نظر إلى الورثة"}],"correct_id":"o1","explanation":"قرر الكتاب أن ما زاد على الثلث من الوصية يحتاج موافقة الورثة.","page":116},{"id":"u03_l04_q145","lesson_id":"u03_l04","difficulty":"medium","prompt":"ما الحكمة من عدم الإيصاء لوارث إلا بموافقة بقية الورثة بعد الوفاة؟","options":[{"id":"o2","text":"زيادة الخصومة الأسرية"},{"id":"o4","text":"السماح باستئثار وارث بالتركة كلها"},{"id":"o1","text":"منع التفضيل المؤدي إلى النزاع والحسد بين الورثة"},{"id":"o3","text":"إلغاء نصيب الوارث الأصلي"}],"correct_id":"o1","explanation":"أورد الدرس منع الوصية للوارث إلا بإجازة الورثة وعلله بمنع النزاع.","page":116},{"id":"u03_l04_q148","lesson_id":"u03_l04","difficulty":"medium","prompt":"ما الفرق بين الوصية المالية وبين وصية الأهل بالمحافظة على الصلاة بحسب الإثراء؟","options":[{"id":"o4","text":"الأولى لا يجوز كتابتها"},{"id":"o2","text":"كلتاهما تقتضيان نقل ملكية أرض فورًا"},{"id":"o3","text":"الثانية وسيلة لحرمان الورثة من نصيبهم"},{"id":"o1","text":"الأولى تبرع ينفذ بعد الوفاة والثانية نصيحة بالخير والمعروف"}],"correct_id":"o1","explanation":"أورد الكتاب النصح للأهل بالصلاة وصلة الأرحام إضافة إلى الوصية بالمال.","page":117},{"id":"u03_l04_q151","lesson_id":"u03_l04","difficulty":"medium","prompt":"إذا أراد مسلم أن ينفع الفقراء بجزء من ماله بعد وفاته، فأي صفة تجعل التصرف وصية لا تبرعًا منجزًا؟","options":[{"id":"o3","text":"أن يكون التصرف قرضًا مستردًا"},{"id":"o1","text":"تأجيل تنفيذ التبرع إلى ما بعد الوفاة"},{"id":"o4","text":"أن يُباع المال بلا تحديد للمستفيد"},{"id":"o2","text":"حصول التبرع وتسليم المال فورًا في حياته"}],"correct_id":"o1","explanation":"عرّف الكتاب الوصية بأنها تبرع يقرره الشخص في حياته وينفذ بعد موته.","page":115},{"id":"u03_l04_q152","lesson_id":"u03_l04","difficulty":"hard","prompt":"ما أثر تخصيص وصية لغير الوارث من الأقارب المحتاجين كما يوضح مقصد التشريع؟","options":[{"id":"o4","text":"منع عمل الخير بعد وفاة صاحب المال"},{"id":"o3","text":"اعتبار صلة الرحم مقتصرة على الأموال"},{"id":"o1","text":"تقوية التكافل وصلة الرحم دون الإضرار بحقوق الورثة"},{"id":"o2","text":"إلغاء أنصبة جميع الورثة بقرار فردي"}],"correct_id":"o1","explanation":"ذكر الدرس التكافل والمحبة بين الأقارب من غير الوارثين من حكم الوصية.","page":115},{"id":"u03_l04_q154","lesson_id":"u03_l04","difficulty":"hard","prompt":"ما المقصد من تفضيل ترك الورثة في غنى على جعلهم يسألون الناس؟","options":[{"id":"o4","text":"منع التبرع المستحب في كل صورة"},{"id":"o1","text":"الجمع بين الإحسان بالوصية وحفظ حاجة الأسرة والورثة"},{"id":"o3","text":"اشتراط أن تكون الوصية بجميع الممتلكات"},{"id":"o2","text":"جعل الوصية سببًا مقصودًا لإفقار الأسرة"}],"correct_id":"o1","explanation":"استشهد الكتاب بحديث سعد بن أبي وقاص لبيان الاعتدال وحفظ حقوق الورثة.","page":116},{"id":"u03_l04_q155","lesson_id":"u03_l04","difficulty":"medium","prompt":"متى تصبح وصية خاصة لأحد الورثة قابلة للتنفيذ وفق الشرط المذكور؟","options":[{"id":"o4","text":"حين تكون شفوية ولا يعلم بها أحد"},{"id":"o3","text":"بمجرد رغبة الموصي دون أي شرط"},{"id":"o1","text":"عندما يوافق عليها جميع الورثة بعد وفاة الموصي"},{"id":"o2","text":"عند إخفائها عن بقية الورثة"}],"correct_id":"o1","explanation":"ربط الكتاب تنفيذ الوصية للوارث بإجازة بقية الورثة بعد الوفاة.","page":116},{"id":"u03_l04_q158","lesson_id":"u03_l04","difficulty":"medium","prompt":"أي صورة من الوصايا تتعلق بالحقوق المعنوية والدينية لا بنقل مال بعد الوفاة؟","options":[{"id":"o4","text":"أن يمنع توثيق ما عليه من حقوق"},{"id":"o2","text":"أن يوصي بحرمان الورثة من حقوقهم"},{"id":"o3","text":"أن يجعل الوصية وسيلة لإخفاء الديون"},{"id":"o1","text":"أن يوصي الإنسان أهله بالمحافظة على الصلاة وصلة الأرحام"}],"correct_id":"o1","explanation":"ذكرت صفحة الإثراء الوصية بالنصح وصلة الرحم وأداء الصلاة إلى جانب الوصية المالية.","page":117},{"id":"u03_l04_q162","lesson_id":"u03_l04","difficulty":"medium","prompt":"ما المقصد الاجتماعي الذي يبرر الوصية لغير الوارث المحتاج؟","options":[{"id":"o2","text":"الالتفاف على حقوق الورثة لإلحاق الأذى بهم"},{"id":"o4","text":"تعطيل توزيع الميراث بعد الوفاة"},{"id":"o3","text":"حصر البر في الأقارب الوارثين فقط"},{"id":"o1","text":"تقوية التكافل وسد حاجة المحتاجين"}],"correct_id":"o1","explanation":"ذكر الكتاب تحقيق التكافل الاجتماعي وصلة غير الوارثين من حكم الوصية.","page":115}]$wall_questions$::jsonb)
